namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await httpClient.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await httpClient.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await httpClient.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(customerEmail)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await httpClient.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.Today.AddDays(-3), EstimatedDelivery = DateTime.Today.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-001235", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.Today.AddDays(-5), EstimatedDelivery = DateTime.Today, CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-001236", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(4), CustomerEmail = "alice@example.com", Description = "Medical supplies" },
        new() { Id = 4, TrackingNumber = "TRK-001237", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Today.AddDays(-7), EstimatedDelivery = DateTime.Today.AddDays(-1), CustomerEmail = "carol@example.com", Description = "Auto parts - 3 crates" },
        new() { Id = 5, TrackingNumber = "TRK-001238", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.Today.AddDays(-4), EstimatedDelivery = DateTime.Today.AddDays(3), CustomerEmail = "bob@example.com", Description = "Perishable goods - refrigerated" },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        var shipments = _shipments.Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase)).ToList();
        return Task.FromResult(shipments);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001234)"
                   @bind="_trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">
                Track
            </button>
        </div>
    </div>
</div>

@if (_isSearching)
{
    <p><em>Searching...</em></p>
}
else if (_searched && _shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@_lastSearched</strong>".
    </div>
}
else if (_shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @_shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@_shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@_shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@_shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd>
                            <span class="badge @GetStatusBadgeClass(_shipment.Status) fs-6">
                                @_shipment.Status
                            </span>
                        </dd>
                        <dt>Shipped Date</dt>
                        <dd>@_shipment.ShippedDate.ToShortDateString()</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold">@_shipment.EstimatedDelivery.ToShortDateString()</dd>
                    </dl>
                </div>
            </div>

            @if (_shipment.Status == ShipmentStatus.Delayed)
            {
                <div class="alert alert-danger mt-3">
                    ⚠️ This shipment is currently delayed. The estimated delivery date may change.
                </div>
            }
            else if (_shipment.Status == ShipmentStatus.Delivered)
            {
                <div class="alert alert-success mt-3">
                    ✅ This shipment has been delivered.
                </div>
            }
        </div>
    </div>
}

<hr class="my-4" />

<h3>My Shipments</h3>
@if (_customerShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (_customerShipments.Count == 0)
{
    <p class="text-muted">No shipments found for your account.</p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in _customerShipments)
            {
                <tr @onclick="() => ViewShipment(s)" style="cursor: pointer;">
                    <td>@s.TrackingNumber</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string _trackingNumber = string.Empty;
    private string _lastSearched = string.Empty;
    private Shipment? _shipment;
    private bool _searched;
    private bool _isSearching;
    private List<Shipment>? _customerShipments;

    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? string.Empty;
            if (!string.IsNullOrEmpty(email))
            {
                _customerShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
        }
        _customerShipments ??= [];
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(_trackingNumber)) return;

        _isSearching = true;
        _lastSearched = _trackingNumber;
        _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_trackingNumber.Trim());
        _searched = true;
        _isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private void ViewShipment(Shipment shipment)
    {
        _shipment = shipment;
        _trackingNumber = shipment.TrackingNumber;
        _lastSearched = shipment.TrackingNumber;
        _searched = true;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };
}

